"""Islamic History XII PDF6: pp.6–7 — Lesson 1: beginning of the Abbasid caliphate; Imamiyyah, Zaydiyyah, Kaysaniyyah. Run: python class12_ihist_page006.py"""
from class12_ihist_common import BOOK, Builder, rec, P


def p6():
    b = Builder()
    b.h('Beginning of the Abbasid caliphate', 'آغاز خلافت بنوعباس', 'د بنو عباس د خلافت پیل')
    P(b, [('Hazrat Abbas bin Abd al-Muttalib was the uncle of Huzoor ﷺ. The caliphs of the Banu Abbas belonged to the family of Hazrat Abbas (may Allah be pleased with him); by this relation they were called the Banu Abbas. The Banu Abbas remained in power for approximately five hundred years. Along with worldly rule, every ruler was also considered the religious leader of the Muslims. The events of the setting of the sun of the power of the Banu Umayyah and of the Banu Abbas coming to power are very instructive and regrettable. After the martyrdom of Hazrat Imam Husayn (may Allah be pleased with him), the Shi\'an of Ali became divided into three groups.', 'حضرت عباس بن عبدالمطلب حضور صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم کے چچا تھے۔ بنو عباس کے خلفاء کا تعلق حضرت عباس رضی اللہ تعالیٰ عنہ کے خاندان سے تھا۔ اسی نسبت سے یہ بنو عباس کہلائے۔ بنو عباس تقریباً پانچ سو سال برسرِ اقتدار رہے۔ دنیاوی حکمرانی کے ساتھ ساتھ ہر حکمران مسلمانوں کا دینی پیشوا بھی تصور کیا جاتا تھا۔ بنو امیہ کے اقتدار کا سورج غروب ہونے اور بنو عباس کے اقتدار میں آنے کے واقعات بہت سبق آموز اور قابلِ افسوس ہیں۔ حضرت امام حسین رضی اللہ تعالیٰ عنہ کی شہادت کے بعد شیعانِ علی تین گروہوں میں تقسیم ہو گئے۔', 'حضرت عباس بن عبدالمطلب د حضور ﷺ تره و. د بنو عباس خلفاء د حضرت عباس رضي الله عنه له کورنۍ وو؛ د همدې نسبت له امله بنو عباس وبلل شول. بنو عباس نږدې پنځه سوه کاله واک کې وو. له دنیوي واکمنۍ سره هر واکمن د مسلمانانو دیني مشر هم ګڼل کېده. د بنو امیه د واک د لمر لوېدو او د بنو عباس واک ته د رسېدو پېښې ډېرې عبرتناکې او د افسوس وړ دي. د حضرت امام حسین رضي الله عنه له شهادت وروسته د علي شیعه په درېیو ډلو ووېشل شول.'),
          ('Their details are as follows.', 'ان کی تفصیل درج ذیل ہے۔', 'تفصیل یې دا ده.')])
    b.h('1. The Imamiyyah sect', '۱۔ فرقہ امامیہ:', '۱. امامیه فرقه')
    P(b, [('The belief of the people of this sect was that the imamate is the right only of the Fatimid descendants of Hazrat Ali (may Allah be pleased with him). The people of this sect accepted as their imam Zayn al-Abidin (Ali bin Husayn, may Allah be pleased with him), son of Hazrat Imam Husayn (may Allah be pleased with him).', 'اس فرقے کے لوگوں کا عقیدہ یہ تھا کہ امامت صرف حضرت علی رضی اللہ تعالیٰ عنہ کی فاطمی اولاد کا حق ہے۔ اس فرقے کے لوگوں نے حضرت امام حسین رضی اللہ تعالیٰ عنہ کے بیٹے زین العابدین (علی بن حسین رضی اللہ تعالیٰ عنہ) کو اپنا امام تسلیم کر لیا۔', 'د دې فرقې د خلکو عقیده دا وه چې امامت یوازې د حضرت علي رضي الله عنه د فاطمي اولاد حق دی. د دې فرقې خلکو د حضرت امام حسین رضي الله عنه زوی زین العابدین (علي بن حسین رضي الله عنه) خپل امام ومانه.'),
          ('When Hazrat Ali bin Husayn (may Allah be pleased with him) departed from this transitory world, his elder son Imam Baqir was accepted as his successor. After him the imamate of his son Ja\'far Sadiq was accepted. Since the people of this sect had accepted the caliphate of the Banu Umayyah, they did not demand the caliphate.', 'حضرت علی بن حسین رضی اللہ تعالیٰ عنہ جب اس جہانِ فانی سے رخصت ہوئے تو ان کے بڑے بیٹے امام باقر کو ان کا جانشین تسلیم کیا گیا۔ ان کے بعد ان کے بیٹے جعفر صادق کی امامت کو تسلیم کیا گیا۔ اس فرقے کے لوگوں نے چونکہ بنو امیہ کی خلافت کو تسلیم کر لیا تھا اس لئے انہوں نے خلافت کا مطالبہ نہیں کیا۔', 'کله چې حضرت علي بن حسین رضي الله عنه له دې فاني نړۍ رخصت شو، مشر زوی یې امام باقر د هغه ځای‌ناستی ومنل شو. له هغه وروسته د هغه د زوی جعفر صادق امامت ومنل شو. څرنګه چې د دې فرقې خلکو د بنو امیه خلافت منلی و، نو د خلافت غوښتنه یې ونه کړه.')])
    r1 = rec(b, 1, 6, 6, [6], first=True)
    t = Builder()
    t.h('2. The Zaydiyyah sect', '۲۔ فرقہ زیدیہ:', '۲. زیدیه فرقه')
    t.p('Considerable similarity is found in the beliefs of the people of this sect and the Imamiyyah sect. Its belief was that Hazrat Ali (may Allah be pleased with him) is the wasi (designated heir) of Hazrat Muhammad, the Messenger of Allah, the Seal of the Prophets ﷺ. In this respect this sect accepts Hazrat Ali (may Allah be pleased with him) as the first imam. They believe Hazrat Imam Hasan (may Allah be pleased with him) to be the second, Hazrat Imam Husayn (may Allah be pleased with him) the third, and Hazrat Ali bin Husayn (may Allah be pleased with him) (Zayn al-Abidin) the fourth imam. After this, a difference arose between both sects. The followers of the Imamiyyah sect were in favour of Baqir, whereas those of the Zaydiyyah sect accepted Imam Zayd as their imam. By this relation these people are called Zaydis. The people of this sect announced the caliphate of Imam Zayd in Kufah, but Imam Zayd was arrested and killed. His successor Imam Yahya too was arrested and killed. These people wanted the caliphate along with the imamate.', 'اس فرقے اور امامیہ فرقے کے لوگوں کے عقائد میں کافی مماثلت پائی جاتی ہے۔ ان کا عقیدہ یہ تھا کہ حضرت علی رضی اللہ تعالیٰ عنہ حضرت محمد رسول اللہ خاتم النبیین صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم کے وصی ہیں۔ اس نسبت سے یہ فرقہ حضرت علی رضی اللہ تعالیٰ عنہ کو پہلا امام تسلیم کرتا ہے۔ حضرت امام حسن رضی اللہ تعالیٰ عنہ کو دوسرا، حضرت امام حسین رضی اللہ تعالیٰ عنہ کو تیسرا اور حضرت علی بن حسین رضی اللہ تعالیٰ عنہ (زین العابدین) کو چوتھا امام مانتے ہیں۔ اس کے بعد دونوں فرقوں میں اختلاف پیدا ہو گیا۔ فرقہ امامیہ کے پیروکار باقر کے حق میں تھے جبکہ فرقہ زیدیہ والے امام زید کو اپنا امام تسلیم کرتے تھے۔ اسی نسبت سے یہ لوگ زیدی کہلاتے ہیں۔ اس فرقے کے لوگوں نے کوفہ میں امام زید کی خلافت کا اعلان کیا لیکن امام زید گرفتار ہو کر قتل کر دیے گئے۔ ان کے جانشین امام یحییٰ بھی گرفتار کر کے قتل کر دیے گئے۔ یہ لوگ امامت کے ساتھ ساتھ خلافت بھی چاہتے تھے۔', 'د دې فرقې او د امامیه فرقې د خلکو په عقایدو کې ډېر ورته‌والی شته. عقیده یې دا وه چې حضرت علي رضي الله عنه د حضرت محمد رسول الله خاتم النبیین ﷺ وصي دی. له دې نسبته دا فرقه حضرت علي رضي الله عنه لومړی امام مني؛ حضرت امام حسن رضي الله عنه دویم، حضرت امام حسین رضي الله عنه درېیم، او حضرت علي بن حسین رضي الله عنه (زین العابدین) څلورم امام بولي. له دې وروسته د دواړو فرقو ترمنځ اختلاف پیدا شو: د امامیه پیروان د باقر په ګټه وو، او زیدیه امام زید خپل امام ګاڼه؛ له همدې نسبته دا خلک زیدیان بلل کېږي. د دې فرقې خلکو په کوفه کې د امام زید د خلافت اعلان وکړ، خو امام زید ونیول شو او ووژل شو؛ ځای‌ناستی یې امام یحیی هم ونیول شو او ووژل شو. دا خلک له امامت سره خلافت هم غوښتل.')
    t.h('3. The Kaysaniyyah sect', '۳۔ فرقہ کیسانیہ:', '۳. کیسانیه فرقه')
    t.p('The foundation of this sect was laid by Mukhtar Thaqafi for attaining his political aims. Mukhtar Thaqafi was an extremely cunning man and was desirous of attaining awe and dominance. He wanted to attain power at any cost. After the incident of Karbala the Islamic community had become a victim of disarray. Mukhtar Thaqafi wanted to take advantage of this disarray and confusion. For this purpose he began to gather people by raising the slogan of retribution for Husayn (may Allah be pleased with him). First of all Mukhtar requested Imam Zayn al-Abidin that he …', 'اس فرقے کی بنیاد مختار ثقفی نے اپنے سیاسی مقاصد حاصل کرنے کے لئے رکھی۔ مختار ثقفی انتہائی مکار آدمی تھا اور رعب و دبدبہ حاصل کرنے کا خواہاں تھا۔ وہ ہر قیمت پر اقتدار حاصل کرنا چاہتا تھا۔ واقعہ کربلا کے بعد ملتِ اسلامیہ انتشار کا شکار ہو گئی تھی۔ مختار ثقفی اس انتشار اور افراتفری سے فائدہ اٹھانا چاہتا تھا۔ اس نے اس مقصد کے حصول کے لئے قصاصِ حسین رضی اللہ تعالیٰ عنہ کا نعرہ لگا کر لوگوں کو اکٹھا کرنا شروع کیا، مختار نے سب سے پہلے امام زین العابدین سے درخواست کی کہ وہ', 'د دې فرقې بنسټ مختار ثقفي د خپلو سیاسي موخو د ترلاسه کولو لپاره کېښود. مختار ثقفي ډېر چالاک سړی و او د رعب او دبدبې غوښتونکی و؛ په هره بیه یې واک غوښت. د کربلا له پېښې وروسته اسلامي ملت د ګډوډۍ ښکار شوی و. مختار ثقفي غوښتل له دې ګډوډۍ او ګډوډي حالت ګټه واخلي. د دې موخې لپاره یې د حسین رضي الله عنه د قصاص شعار پورته کړ او خلک یې راټولول پیل کړل. مختار تر ټولو مخکې له امام زین العابدین غوښتنه وکړه چې هغه …')
    BOOK.save(6, [(1, r1), (1, rec(t, 1, 7, 6, [7]))], issues=[{'id': 'ihist12-pdf006', 'unit': 1, 'printedPage': 6,
               'description': 'Lesson 1 opens on p.6. Student pen mark ("①" and a circle) in the first paragraph excluded; "Not For Sale" headers and website watermark excluded.'}])


if __name__ == '__main__':
    p6()
